// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address actor1, address actor2) public {
        vm.assume(actor1 != address(c) && actor1 != address(this));
        vm.assume(actor2 != address(c) && actor2 != address(this) && actor2 != actor1);
        amount = bound(amount, 1, 1e30);
        vm.deal(address(c), amount);
        c.withdrawAll();
        assertTrue(address(c).balance == 0);
    }
}
